(* Build permissive chain *)
All_OK := Pressure_OK
          AND Temperature_OK
          AND Level_OK
          AND Emergency_Stop        (* NC: TRUE = healthy *)
          AND NOT Abort_PB
          AND NOT Fault_State;

(* Gate all outputs through permissive *)
Reactor_Heater := Heater_Command AND All_OK;
Feed_Pump      := Pump_Command AND All_OK;
Agitator       := Agitator_Command AND All_OK;

(* Permissive status to HMI *)
System_Ready := All_OK;
